\label[corollary]{cor:elementary-laws}
Under the hypotheses of \cref{thm:cyclicity}, an elementary law satisfies
\(P(Z;x,y)=p_m(Z;x,y)^{n/m}\) for a unique divisor \(m\mid n\).

\label[proposition]{prop:coalgebra}
One \(n\)-th of the trace,
\begin{equation}\label{eq:coproduct}
 (\Delta f)(x,y)
 =\frac1n\operatorname{Tr}_{\mathcal A/F}\bigl(\operatorname{mult}_{f(Z)}\bigr)
 =\frac1n\sum_{z\in x*y}f(z)
\end{equation}
defines a linear map \(\Delta:\Bbbk(t)\to\Bbbk(x,y)\).  Whenever the
specializations are defined, fixing the first or the second input gives the
generalized shifts
\begin{equation}\label{eq:shifts}
 (\mathcal L_af)(t)=(\Delta f)(a,t),
 \qquad
 (\mathcal R_bf)(t)=(\Delta f)(t,b)
\end{equation}
as rational operator families.  They satisfy \(\mathcal L_a\mathcal R_b=\mathcal R_b\mathcal L_a\) on their
common domain.  The unit gives
\begin{equation}\label{eq:shift-unit}
 \mathcal L_0=\mathcal R_0=\operatorname{id},
 \qquad (\mathcal L_af)(0)=(\mathcal R_af)(0)=f(a).
\end{equation}
The last two evaluations hold whenever \(f\) is regular at \(a\).

\label[proposition]{prop:trace-differential}
Let \(K=\Bbbk(t)\) and let \(Q(Z;s)\in K[[s]][Z]\) be monic of degree
\(n\) in \(Z\), with \(Q(Z;0)=(Z-t)^n\).  Put
\(\mathcal A=K[[s]][Z]/(Q)\) and define
\begin{equation}\label{eq:local-trace-family}
 (\mathcal T_sf)(t)
 =\frac1n\operatorname{Tr}_{\mathcal A/K[[s]]}\bigl(\operatorname{mult}_{f(Z)}\bigr),
 \qquad f\in K.
\end{equation}
If \(\mathcal T_s=\sum_{r\geq0}s^rA_r\), then
\begin{equation}\label{eq:local-differential-coefficients}
 A_r\in \Bbbk(t)\langle\partial_t\rangle,
 \qquad [\partial_t,t]=1,
\end{equation}
and its differential order is at most \(n(r+1)-1\).

\label[lemma]{lem:exp-independence}
Let \(L\) be a field of characteristic zero, let \(\alpha_1,\dots,\alpha_s\in L\) be pairwise distinct, and let \(q_1(T),\dots,q_s(T)\in L[T]\) be arbitrary polynomials. If
\begin{equation}\label{eq:exp-relation}
 \sum_{i=1}^s e^{\alpha_iT}q_i(T)=0
 \qquad\text{in }L[[T]],
\end{equation}
then \(q_i=0\) for every \(i\).

\label[proposition]{prop:polynomial-pullback}
Let \(X=\mathbb A^1_{\mathbb C}\) carry an algebraic \(n\)-valued monoid with
strong unit \(0\), represented by the roots of \(P(z;x,y)\). Let
\(T\in\mathbb C[z]\) have degree \(m\geq2\) and satisfy \(T(0)=0\). Then
\begin{equation}\label{eq:polynomial-pullback}
 a\circ_T b
 =\bigsqcup_{u\in T(a)*T(b)}T^{-1}[u]
 =\mathopen{[}z\mathbin{|}P(T(z);T(a),T(b))=0\mathclose{]}
\end{equation}
defines an algebraic \(mn\)-valued monoid with weak unit \(0\). If
the law on \(X\) is commutative, then so is its pullback.
